import { useWriteContract, useAccount, useWaitForTransactionReceipt, useReadContract, useBalance, usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { useConnectModal } from '@rainbow-me/rainbowkit'
import { useState, useEffect, useCallback, useSyncExternalStore } from 'react'

function subscribeNoPw(cb) { window.addEventListener('uc_hide_nopw', cb); return () => window.removeEventListener('uc_hide_nopw', cb) }
function getNoPwHidden() { return !!localStorage.getItem('uc_hide_nopw') }
import { parseUnits, formatUnits, isAddress } from 'viem'
import { SAFE_ABI } from './abi.js'
import { getSafeAddress } from './config.js'
import { getChainInfo, getTxUrl, fmtDisplay, fmtErr } from './chainUtils.js'
import { useTxHistory } from './useTxHistory.js'
import PctBtns from './PctBtns.jsx'
import { getTokens, defaultPresets, NATIVE } from './tokenList.js'
import SafeAssets from './SafeAssets.jsx'

const ERC20_ABI = [
  { type:'function', name:'allowance', inputs:[{type:'address'},{type:'address'}], outputs:[{type:'uint256'}], stateMutability:'view' },
  { type:'function', name:'approve',   inputs:[{type:'address'},{type:'uint256'}], outputs:[{type:'bool'}],   stateMutability:'nonpayable' },
  { type:'function', name:'symbol',    inputs:[], outputs:[{type:'string'}], stateMutability:'view' },
  { type:'function', name:'decimals',  inputs:[], outputs:[{type:'uint8'}],  stateMutability:'view' },
]

function sanitizeAmount(v) {
  return v.replace(/[^0-9.]/g, '').replace(/^(\d*\.?\d*).*$/, '$1')
}

export default function SafeDeposit({ onGoToPassword }) {
  const noPwHidden = useSyncExternalStore(subscribeNoPw, getNoPwHidden)
  const { address } = useAccount()
  const { openConnectModal } = useConnectModal()
  const { activeChainId: chainId } = useGuestChain()
  const { currency } = getChainInfo(chainId)
  const { addTx } = useTxHistory()
  const publicClient = usePublicClient()
  const SAFE_ADDRESS = getSafeAddress(chainId)

  const presetTokens = getTokens(chainId)
  const [token, setToken] = useState(presetTokens[0])
  const [customAddr, setCustomAddr] = useState('')
  const [customErr, setCustomErr] = useState('')
  const [showCustom, setShowCustom] = useState(false)
  const [extraTokens, setExtraTokens] = useState({})
  const handleTokenLoaded = useCallback(t => setExtraTokens(prev => ({ ...prev, [t.address.toLowerCase()]: t })), [])
  const [approveStep, setApproveStep] = useState('idle')

  const [amount, setAmount] = useState('')
  const [status, setStatus] = useState('')
  const [txHash, setTxHash] = useState(null)
  const { writeContractAsync, isPending } = useWriteContract()
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({ hash: txHash })

  const isNative = token.address === NATIVE

  const { data: safeBalance, refetch: refetchBalance } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'balances',
    args: [address ?? NATIVE, token.address],
    chainId,
    query: { enabled: !!address },
  })
  const { data: guardian } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'guardians',
    args: [address ?? NATIVE],
    chainId,
    query: { enabled: !!address },
  })
  const { data: walletBalance } = useBalance({
    address,
    token: isNative ? undefined : token.address,
    chainId,
    query: { enabled: !!address },
  })

  useEffect(() => {
    setToken(getTokens(chainId)[0]); setAmount(''); setStatus(''); setTxHash(null)
    setApproveStep('idle'); setShowCustom(false); setCustomAddr(''); setCustomErr('')
  }, [chainId]) // eslint-disable-line
  useEffect(() => { if (isSuccess) refetchBalance() }, [isSuccess]) // eslint-disable-line

  const hasGuardian = guardian && guardian !== NATIVE
  const PRESETS = defaultPresets(token)
  const amountNum = parseFloat(amount)
  const walletNum = walletBalance ? parseFloat(formatUnits(walletBalance.value, token.decimals)) : null
  const amountErr = amount && (isNaN(amountNum) || amountNum <= 0) ? 'Amount must be > 0'
    : amount && walletNum !== null && amountNum > walletNum ? `Insufficient balance (max ${fmtDisplay(walletBalance.value, token.decimals)} ${token.symbol})` : ''



  function selectPreset(t) {
    setToken(t); setShowCustom(false); setCustomAddr(''); setCustomErr('')
    setAmount(''); setApproveStep('idle')
  }

  async function resolveCustom(addr) {
    setCustomErr('')
    if (!addr) return
    if (!isAddress(addr)) { setCustomErr('Invalid address'); return }
    try {
      const [sym, dec] = await Promise.all([
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'symbol' }),
        publicClient.readContract({ address: addr, abi: ERC20_ABI, functionName: 'decimals' }),
      ])
      setToken({ symbol: sym, address: addr.toLowerCase(), decimals: Number(dec) })
    } catch { setCustomErr('Could not read token — check address') }
  }

  async function handleDeposit() {
    if (!amount || !address || amountErr) return
    try {
      const amtWei = parseUnits(amount, token.decimals)

      if (!isNative && approveStep !== 'approved') {
        const allowance = await publicClient.readContract({
          address: token.address, abi: ERC20_ABI, functionName: 'allowance',
          args: [address, SAFE_ADDRESS],
        })
        if (allowance < amtWei) {
          setApproveStep('approving')
          setStatus('info:Approving ' + token.symbol + '…')
          const appHash = await writeContractAsync({
            address: token.address, abi: ERC20_ABI, functionName: 'approve',
            args: [SAFE_ADDRESS, amtWei],
          })
          await publicClient.waitForTransactionReceipt({ hash: appHash })
          setApproveStep('approved')
          setStatus('')
        } else {
          setApproveStep('approved')
        }
      }

      setStatus('info:Confirm in wallet…')
      const hash = await writeContractAsync({
        address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'deposit',
        args: [token.address, amtWei],
        value: isNative ? amtWei : 0n,
      })
      setTxHash(hash)
      setStatus('info:Confirming…')
      addTx({ hash, type: 'Safe Deposit', amount, currency: token.symbol, chainId, status: 'pending' })
      setApproveStep('idle')
    } catch (e) {
      setApproveStep('idle')
      setStatus('err:' + fmtErr(e))
    }
  }

  const txUrl = txHash ? getTxUrl(chainId, txHash) : null
  const displayStatus = isSuccess ? `ok:✅ Deposited ${amount} ${token.symbol}` : status
  const [dtype, dmsg] = displayStatus.includes(':') ? displayStatus.split(/:(.+)/) : ['info', displayStatus]

  return (
    <div className="card">
      <h2>Safe Deposit</h2>
      <p className="sub">Deposit into Uniswap v4 PoolManager. Withdraw any amount anytime.</p>

      {/* Token picker */}
      <SafeAssets onTokensLoaded={handleTokenLoaded} />
      <div className="token-picker">
        {presetTokens.map(t => (
          <button key={t.address} className={`token-btn ${token.address === t.address ? 'active' : ''}`}
            onClick={() => selectPreset(t)}>{t.symbol}</button>
        ))}
        {Object.values(extraTokens)
          .filter(t => !presetTokens.find(p => p.address.toLowerCase() === t.address.toLowerCase()))
          .map(t => (
            <button key={t.address} className={`token-btn ${token.address === t.address.toLowerCase() ? 'active' : ''}`}
              onClick={() => selectPreset(t)}>{t.symbol}</button>
          ))}
        <button className={`token-btn ${showCustom ? 'active' : ''}`}
          onClick={() => setShowCustom(s => !s)}>+ Custom</button>
      </div>

      {showCustom && (
        <div style={{marginBottom:'12px'}}>
          <div className="token-custom-wrap">
            <input className={`token-custom-input ${customErr ? 'err' : ''}`}
              placeholder="Token contract address (0x…)"
              value={customAddr}
              onChange={e => setCustomAddr(e.target.value)}
              onBlur={() => resolveCustom(customAddr)} />
            <button className="btn-copy" onClick={() => resolveCustom(customAddr)}>Load</button>
          </div>
          {customErr && <div className="token-custom-label" style={{color:'#f43f5e'}}>{customErr}</div>}
          {!customErr && token.address === customAddr?.toLowerCase() && customAddr && (
            <div className="token-custom-label">✓ {token.symbol} · {token.decimals} decimals</div>
          )}
        </div>
      )}

      <div className="presets">
        {PRESETS.map(p => <button key={p} className={`preset ${amount === p ? 'active' : ''}`} onClick={() => setAmount(p)}>{p} {token.symbol}</button>)}
      </div>

      <div className={`input-panel ${amountErr ? 'input-err' : ''}`}>
        <div className="input-panel-label">Amount</div>
        <div className="input-panel-row">
          <input className="input-big" type="text" inputMode="decimal" placeholder="0"
            value={amount} onChange={e => setAmount(sanitizeAmount(e.target.value))} />
          <div className="input-currency"><span className="token-sym-dot" />{token.symbol}</div>
        </div>
        <div className="input-balance">
          <span>{walletBalance ? `💳 ${fmtDisplay(walletBalance.value, token.decimals)} · 🏦 ${safeBalance !== undefined ? fmtDisplay(safeBalance, token.decimals) : '…'} ${token.symbol}` : ''}</span>

        </div>
        {walletBalance && <PctBtns balance={walletBalance.value} decimals={token.decimals} isNative={isNative} amount={amount} setAmount={setAmount} />}
      </div>
      {amountErr && <div className="status err">{amountErr}</div>}

      {address && !hasGuardian&& !noPwHidden && (
        <div className="status warn" style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:'8px'}}>
          <span>⚠️ No password set — vault is unprotected</span>
          <div style={{display:'flex',gap:'6px',flexShrink:0}}>
            <button className="btn-copy" style={{whiteSpace:'nowrap'}} onClick={onGoToPassword}>Set Password →</button>
            <button className="btn-copy" style={{whiteSpace:'nowrap'}} onClick={() => { localStorage.setItem('uc_hide_nopw','1'); window.dispatchEvent(new Event('uc_hide_nopw')) }}>✕</button>
          </div>
        </div>
      )}

      <button className="btn-primary" onClick={!address ? openConnectModal : handleDeposit}
        disabled={(!!address && (!amount || !!amountErr)) || isPending || isConfirming || approveStep === 'approving'}>
        {approveStep === 'approving' ? <><span className="spinner" /> Approving {token.symbol}…</>
          : isPending ? <><span className="spinner" /> Confirm in wallet…</>
          : isConfirming ? <><span className="spinner" /> Confirming…</>
          : !address ? 'Connect' : `Deposit ${token.symbol}`}
      </button>
      {displayStatus && (
        <div className={`status ${dtype}`}>
          {dmsg}
          {txUrl && (isSuccess || isConfirming) && <> · <a href={txUrl} target="_blank" rel="noreferrer">View ↗</a></>}
        </div>
      )}
    </div>
  )
}
